{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-FB7WeN/src/diff.js","content":"/**
 * Line-level diff of a side against a base, following the exact tie-break
 * rule the specification requires: among longest common subsequences, take
 * the one whose matches come earliest, preferring to advance the base line
 * when the two remaining subsequence lengths are tied.
 */

/**
 * Build the suffix LCS-length table for `base` against `side`.
 * `table[i][j]` holds the length of the longest common subsequence of
 * `base[i:]` and `side[j:]`.
 */
function buildTable(base, side) {
  const m = base.length
  const n = side.length
  const table = new Array(m + 1)
  for (let i = 0; i <= m; i++) table[i] = new Int32Array(n + 1)
  for (let i = m - 1; i >= 0; i--) {
    const row = table[i]
    const nextRow = table[i + 1]
    for (let j = n - 1; j >= 0; j--) {
      row[j] = base[i] === side[j] ? nextRow[j + 1] + 1 : Math.max(nextRow[j], row[j + 1])
    }
  }
  return table
}

/**
 * Diff `side` against `base`. Returns the list of changes (each a run of
 * base lines replaced by a run of side lines, described by half-open index
 * ranges) and `baseToSide`, a map from every base index to the
 * corresponding side index reached by the walk at that point.
 */
export function diffAgainstBase(base, side) {
  const m = base.length
  const n = side.length
  const table = buildTable(base, side)
  const baseToSide = new Array(m + 1)
  const changes = []

  let i = 0
  let j = 0
  let gapBaseStart = 0
  let gapSideStart = 0
  baseToSide[0] = 0

  while (i < m || j < n) {
    if (i < m && j < n && base[i] === side[j]) {
      if (i > gapBaseStart || j > gapSideStart) {
        changes.push({ baseStart: gapBaseStart, baseEnd: i, sideStart: gapSideStart, sideEnd: j })
      }
      i++
      j++
      baseToSide[i] = j
      gapBaseStart = i
      gapSideStart = j
      continue
    }
    if (i < m && (j >= n || table[i + 1][j] >= table[i][j + 1])) {
      i++
      baseToSide[i] = j
    } else {
      j++
    }
  }
  if (i > gapBaseStart || j > gapSideStart) {
    changes.push({ baseStart: gapBaseStart, baseEnd: i, sideStart: gapSideStart, sideEnd: j })
  }

  return { changes, baseToSide }
}
"}

