{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260922T231236Z/cell-FB7WeN/src/merge.js","content":"import { diffAgainstBase } from './diff.js'

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let k = 0; k < a.length; k++) if (a[k] !== b[k]) return false
  return true
}

/**
 * Group a base range into alternating stable stretches and regions where at
 * least one side changed, following the absorption rule: a region runs from
 * a change's base start to its base end, growing to cover every later
 * change that starts at or before the region's current end.
 */
function buildRegions(baseLength, changes) {
  const sorted = [...changes].sort((a, b) => a.baseStart - b.baseStart)
  const merged = []
  for (const change of sorted) {
    const last = merged[merged.length - 1]
    if (last && change.baseStart <= last.end) {
      last.end = Math.max(last.end, change.baseEnd)
    } else {
      merged.push({ start: change.baseStart, end: change.baseEnd })
    }
  }

  const segments = []
  let pos = 0
  for (const region of merged) {
    if (region.start > pos) segments.push({ type: 'stable', start: pos, end: region.start })
    segments.push({ type: 'region', start: region.start, end: region.end })
    pos = region.end
  }
  if (pos < baseLength) segments.push({ type: 'stable', start: pos, end: baseLength })
  return segments
}

/**
 * Resolve a region given each side's lines and the base's lines for that
 * region, in the order the specification checks them.
 */
function resolveRegion(mineLines, baseLines, theirsLines) {
  if (linesEqual(mineLines, theirsLines)) return { kind: 'both', lines: mineLines }
  if (linesEqual(mineLines, baseLines)) return { kind: 'theirs', lines: theirsLines }
  if (linesEqual(theirsLines, baseLines)) return { kind: 'mine', lines: mineLines }
  return { kind: 'conflict', mine: mineLines, base: baseLines, theirs: theirsLines }
}

/**
 * Compute the three-way merge of `mine` and `theirs` against `base`, as a
 * list of segments in base order. Each segment is either
 * `{ type: 'stable', lines }`, `{ type: 'mine'|'theirs'|'both', lines }`, or
 * `{ type: 'conflict', mine, base, theirs }`.
 */
export function computeMerge(mine, base, theirs) {
  const mineDiff = diffAgainstBase(base, mine)
  const theirsDiff = diffAgainstBase(base, theirs)

  const tagged = [
    ...mineDiff.changes.map(change => ({ ...change, side: 'mine' })),
    ...theirsDiff.changes.map(change => ({ ...change, side: 'theirs' })),
  ]
  const segments = buildRegions(base.length, tagged)

  return segments.map(segment => {
    if (segment.type === 'stable') {
      return { type: 'stable', lines: base.slice(segment.start, segment.end) }
    }
    const mineLines = mine.slice(mineDiff.baseToSide[segment.start], mineDiff.baseToSide[segment.end])
    const theirsLines = theirs.slice(theirsDiff.baseToSide[segment.start], theirsDiff.baseToSide[segment.end])
    const baseLines = base.slice(segment.start, segment.end)
    const resolved = resolveRegion(mineLines, baseLines, theirsLines)
    return resolved.kind === 'conflict'
      ? { type: 'conflict', mine: resolved.mine, base: resolved.base, theirs: resolved.theirs }
      : { type: resolved.kind, lines: resolved.lines }
  })
}
"}

